	elif downtimeBy == 'Category':
		colors = defaultColors
		reasonCodes = []
		for row in data:
			stateType = ' (Planned)' if row['stateTypeName'] == 'Planned Downtime' else ''
			if showAssetName: reasonCodes.append(row['assetName'] + ' - ' + row['stateCategoryName'] + stateType)
			else: reasonCodes.append(row['stateCategoryName'] + stateType)
	elif downtimeBy == 'Item':
		colors = defaultColors
		reasonCodes = []
		for row in data:
			stateType = ' (Planned)' if row['stateTypeName'] == 'Planned Downtime' else ''
			if showAssetName: reasonCodes.append(row['assetName'] + ' - ' + row['stateName'] + ' - ' + (row['itemName'] or 'No Item') + stateType)
			else: reasonCodes.append(row['stateName'] + ' - ' + (row['itemName'] or 'No Item') + stateType)

	colorIndex = 0
	for reasonCode in reasonCodes:
