		if downtimeBy == 'item': intervalLabel =name
		else: intervalLabel = name + stateType

		if showAssetName: intervalLabel = "%s - %s"%(row['assetName'], intervalLabel)
		else: intervalLabel = intervalLabel

		index = reasonCodes.index(intervalLabel)
		try:
			durationSecs = row['durationSecs'] or 0
		except:
			durationSecs = 	row['stateDurationSecs'] or 0

		series[index]['data'][index] = {'x': intervalLabel, 'y': round(durationSecs/60.0,1)}

		totalDurationSecs += durationSecs

	totalMins = float(totalDurationSecs)/60.0
	durationMins = 0		

	if downtimeBy in ('Reason', 'Item'): colName = 'stateName'
	elif downtimeBy == 'Category':	colName = 'stateCategoryName'

	for row in data:
